alter table organizations add column contact_email text not null default 'privacy@findworks.test';
alter table discoveries add column state text not null default 'ACTIVE'; alter table discoveries add column last_activity_at timestamptz not null default now(); alter table discoveries add column retention_due_at timestamptz; alter table discoveries add column deleted_at timestamptz; alter table discoveries add unique(id,organization_id);
create table oauth_clients(id text primary key,name text not null,redirect_uri text not null,scopes text not null,revoked_at timestamptz);
create table oauth_registration_attempts(id uuid primary key,remote_hash char(64) not null,created_at timestamptz not null default now()); create index oauth_registration_attempts_recent on oauth_registration_attempts(remote_hash,created_at);
create table invitation_access_attempts(id uuid primary key,remote_hash char(64) not null,created_at timestamptz not null default now()); create index invitation_access_attempts_recent on invitation_access_attempts(remote_hash,created_at);
create table oauth_codes(hash char(64) primary key,client_id text references oauth_clients(id),membership_id uuid references memberships(id),redirect_uri text not null,challenge text not null,resource text not null,scopes text not null,expires_at timestamptz not null,redeemed_at timestamptz);
create table oauth_grants(id uuid primary key,client_id text references oauth_clients(id),membership_id uuid references memberships(id),resource text not null,scopes text not null,created_at timestamptz default now(),revoked_at timestamptz);
create table oauth_tokens(hash char(64) primary key,grant_id uuid references oauth_grants(id),audience text not null,scopes text not null,expires_at timestamptz not null,revoked_at timestamptz);
create table oauth_signing_keys(id uuid primary key,key_reference text not null,active boolean not null,created_at timestamptz default now()); insert into oauth_signing_keys values(gen_random_uuid(),'managed:pilot',true,now());
create table missions(id uuid primary key,organization_id uuid not null,discovery_id uuid not null,label text not null,current_version int not null,approved_version int,created_at timestamptz default now(),unique(id,organization_id),foreign key(discovery_id,organization_id) references discoveries(id,organization_id) on delete cascade);
create table mission_versions(mission_id uuid not null,organization_id uuid not null,version int not null,state text not null,objective text not null,desired_outcome text not null,interviewee_role text not null,interviewee_relevance text not null,expected_minutes int not null,data_use text not null,created_by uuid references memberships(id),created_at timestamptz default now(),approved_by uuid references memberships(id),approved_at timestamptz,primary key(mission_id,version),unique(mission_id,version,organization_id),foreign key(mission_id,organization_id) references missions(id,organization_id) on delete cascade,check(expected_minutes between 5 and 120));
create table mission_entries(mission_id uuid not null,version int not null,kind text not null,position int not null,value text not null,detail text,primary key(mission_id,version,kind,position),foreign key(mission_id,version) references mission_versions on delete cascade);
create table investigation_items(id uuid primary key,mission_id uuid not null,version int not null,position int not null,gap text not null,why text not null,priority text not null,required boolean not null,context text not null,sufficient text not null,foreign key(mission_id,version) references mission_versions on delete cascade);
create table mission_origins(mission_id uuid not null,version int not null,pointer text not null,authority text not null,author uuid references memberships(id),created_at timestamptz default now(),primary key(mission_id,version,pointer),foreign key(mission_id,version) references mission_versions on delete cascade);
create table project_references(id uuid primary key,mission_id uuid not null,version int not null,kind text not null,locator text not null,line_start int,line_end int,revision text,foreign key(mission_id,version) references mission_versions on delete cascade);
create table submissions(membership_id uuid references memberships(id),tool text not null,submission_id uuid not null,input_hash char(64) not null,discovery_id uuid,mission_id uuid,created_at timestamptz default now(),deleted_at timestamptz,primary key(membership_id,tool,submission_id));
create table domain_outbox(id uuid primary key,organization_id uuid not null,event_type text not null,resource_kind text not null,resource_id uuid not null,state text not null default 'PENDING',created_at timestamptz not null default now());
create table mission_review(mission_id uuid not null,version int not null,checkpoint int not null,primary key(mission_id,version,checkpoint),foreign key(mission_id,version) references mission_versions on delete cascade);
create table participants(id uuid primary key,organization_id uuid not null,discovery_id uuid not null,name text not null,email text not null,unique(id,organization_id),foreign key(discovery_id,organization_id) references discoveries(id,organization_id) on delete cascade);
create table interview_sessions(id uuid primary key,organization_id uuid not null,discovery_id uuid not null,mission_id uuid not null,mission_version int not null,participant_id uuid not null,state text not null default 'NOT_STARTED',revision int not null default 0,extraction_state text not null default 'PENDING',commitment_extension_minutes int not null default 0,started_at timestamptz,completed_at timestamptz,deleted_at timestamptz,unique(id,organization_id),foreign key(discovery_id,organization_id) references discoveries(id,organization_id) on delete cascade,foreign key(mission_id,mission_version,organization_id) references mission_versions(mission_id,version,organization_id),foreign key(participant_id,organization_id) references participants(id,organization_id),check(commitment_extension_minutes between 0 and 120));
create table invitations(id uuid primary key,organization_id uuid not null,session_id uuid not null,recipient_email text not null,token_hash char(64) unique not null,state text not null,expires_at timestamptz not null,delivered_at timestamptz,redeemed_at timestamptz,revoked_at timestamptz,foreign key(session_id,organization_id) references interview_sessions(id,organization_id) on delete cascade);
create table access_grants(id uuid primary key,organization_id uuid not null,session_id uuid not null,token_hash char(64) unique not null,revoked_at timestamptz,last_used_at timestamptz,foreign key(session_id,organization_id) references interview_sessions(id,organization_id) on delete cascade);
create table questions(id uuid primary key,organization_id uuid not null,session_id uuid not null,item_id uuid references investigation_items(id),sequence int not null,text text not null,response_mode text not null default 'FREE_TEXT',clarifies uuid references questions(id),active boolean not null default true,created_at timestamptz default now(),foreign key(session_id,organization_id) references interview_sessions(id,organization_id) on delete cascade,unique(session_id,sequence)); create unique index one_active_question on questions(session_id) where active;
create table question_options(question_id uuid references questions(id) on delete cascade,option_id text not null,position int not null,label text not null,primary key(question_id,option_id));
create table evidence(id uuid primary key,organization_id uuid not null,session_id uuid not null,question_id uuid references questions(id),participant_id uuid,source_type text not null,exact_text text not null,option_id text,option_label text,explanation text,revises uuid references evidence(id),author_membership_id uuid references memberships(id),created_at timestamptz default now(),foreign key(session_id,organization_id) references interview_sessions(id,organization_id) on delete cascade);
create table investigation_results(id uuid primary key,organization_id uuid not null,session_id uuid not null,item_id uuid references investigation_items(id),coverage text not null default 'UNADDRESSED',unique(session_id,item_id),foreign key(session_id,organization_id) references interview_sessions(id,organization_id) on delete cascade);
create table unresolved(id uuid primary key,result_id uuid references investigation_results(id) on delete cascade,evidence_id uuid references evidence(id),kind text not null,summary text not null,reason text not null,owner text,acknowledged boolean not null default false);
create table result_outcomes(id uuid primary key,result_id uuid not null references investigation_results(id) on delete cascade,coverage text not null,category text,summary text not null,created_at timestamptz not null default now());
create table result_outcome_evidence(outcome_id uuid not null references result_outcomes(id) on delete cascade,evidence_id uuid not null references evidence(id),primary key(outcome_id,evidence_id));
create table result_evidence(result_id uuid not null references investigation_results(id) on delete cascade,evidence_id uuid not null references evidence(id),primary key(result_id,evidence_id));
create table unresolved_evidence(unresolved_id uuid not null references unresolved(id) on delete cascade,evidence_id uuid not null references evidence(id),primary key(unresolved_id,evidence_id));
create table runtime_runs(id uuid primary key,organization_id uuid not null,session_id uuid not null,evidence_id uuid references evidence(id),expected_revision int not null,state text not null,attempts int not null default 0,restart_count int not null default 0,lease_until timestamptz,stable_event text,error_code text,created_at timestamptz default now(),foreign key(session_id,organization_id) references interview_sessions(id,organization_id) on delete cascade);
create unique index one_live_runtime_run on runtime_runs(session_id) where state in ('PENDING','RUNNING');
create table runtime_checkpoints(run_id uuid primary key references runtime_runs(id) on delete cascade,session_id uuid not null,mission_version int not null,expected_revision int not null,state text not null,location text not null,checksum char(64) not null,created_at timestamptz default now());
create table runtime_turn_credentials(token_hash char(64) primary key,run_id uuid not null references runtime_runs(id) on delete cascade,expires_at timestamptz not null,used_at timestamptz);
create table email_outbox(id uuid primary key,organization_id uuid not null,invitation_id uuid unique references invitations(id) on delete cascade,kind text not null default 'INVITATION',recipient text not null,encrypted_link bytea not null,state text not null default 'PENDING',attempts int not null default 0,max_attempts int not null default 3,available_at timestamptz not null default now(),lease_until timestamptz,error_code text,created_at timestamptz not null default now());
create table findings_packages(id uuid primary key,organization_id uuid not null,session_id uuid not null unique,current_version int not null default 0,accepted_version int,unique(id,organization_id),foreign key(session_id,organization_id) references interview_sessions(id,organization_id) on delete cascade);
create table package_versions(package_id uuid not null,organization_id uuid not null,version int not null,state text not null,notes text,created_at timestamptz default now(),primary key(package_id,version),unique(package_id,version,organization_id),foreign key(package_id,organization_id) references findings_packages(id,organization_id) on delete cascade);
create table package_results(package_id uuid not null,package_version int not null,result_id uuid not null references investigation_results(id) on delete cascade,primary key(package_id,package_version,result_id),foreign key(package_id,package_version) references package_versions on delete cascade);
create table knowledge_items(id uuid primary key,organization_id uuid not null,result_id uuid references investigation_results(id) on delete cascade,package_id uuid not null,package_version int not null,current_version int not null,foreign key(package_id,package_version,organization_id) references package_versions(package_id,version,organization_id));
create table knowledge_versions(knowledge_id uuid references knowledge_items(id) on delete cascade,version int not null,category text not null,claim text not null,review_state text not null,confirmed boolean not null,corrects int,primary key(knowledge_id,version));
create table knowledge_evidence(knowledge_id uuid not null,knowledge_version int not null,evidence_id uuid references evidence(id),quotation text not null,start_offset int not null,end_offset int not null,primary key(knowledge_id,knowledge_version,evidence_id),foreign key(knowledge_id,knowledge_version) references knowledge_versions on delete cascade);
create table knowledge_links(source_id uuid references knowledge_items(id),target_id uuid references knowledge_items(id),kind text not null,primary key(source_id,target_id,kind));
create table conflict_members(conflict_id uuid not null references unresolved(id) on delete cascade,knowledge_id uuid not null,knowledge_version int not null,primary key(conflict_id,knowledge_id,knowledge_version),foreign key(knowledge_id,knowledge_version) references knowledge_versions on delete cascade);
create table publications(id uuid primary key,organization_id uuid not null,discovery_id uuid not null,package_id uuid not null,package_version int not null,published_at timestamptz default now(),invalidated_at timestamptz,foreign key(discovery_id,organization_id) references discoveries(id,organization_id) on delete cascade,foreign key(package_id,package_version,organization_id) references package_versions(package_id,version,organization_id));
create table test_emails(id uuid primary key,kind text not null,recipient text not null,link text not null,created_at timestamptz default now());
create table fault_controls(kind text primary key,remaining int not null);insert into fault_controls values('runtime',0),('runtime_death',0),('extraction',0),('email',0);
create table audit_events(id uuid primary key,organization_id uuid,actor_kind text not null,actor_id uuid,action text not null,resource_kind text not null,resource_id uuid,outcome text not null,correlation_id uuid not null,created_at timestamptz default now(),expires_at timestamptz default now()+interval '12 months');
create table deletion_ledger(id uuid primary key,organization_id uuid not null,kind text not null,resource_id uuid not null,requested_at timestamptz default now(),purge_due_at timestamptz default now()+interval '7 days',backup_expiry_at timestamptz default now()+interval '30 days',purged_at timestamptz);
create table export_snapshots(id uuid primary key,token_hash char(64) unique not null,membership_id uuid not null references memberships(id),discovery_id uuid not null,package_id uuid not null,package_version int not null,contract_version int not null default 1,as_of timestamptz not null default now(),expires_at timestamptz not null default now()+interval '15 minutes');
create table export_cursors(token_hash char(64) primary key,snapshot_id uuid not null references export_snapshots(id) on delete cascade,result_offset int not null,expires_at timestamptz not null default now()+interval '15 minutes');
create table retention_warnings(discovery_id uuid primary key,warning_at timestamptz not null default now());
create function record_mission_submission() returns trigger language plpgsql as $$
begin
  insert into domain_outbox(id,organization_id,event_type,resource_kind,resource_id)
  select gen_random_uuid(),organization_id,'MISSION_DRAFT_IMPORTED','MISSION',new.mission_id from memberships where id=new.membership_id;
  insert into audit_events(id,organization_id,actor_kind,actor_id,action,resource_kind,resource_id,outcome,correlation_id)
  select gen_random_uuid(),organization_id,'HARNESS',new.membership_id,'MISSION_DRAFT_IMPORTED','DISCOVERY',new.discovery_id,'SUCCEEDED',gen_random_uuid() from memberships where id=new.membership_id;
  return new;
end $$;
create trigger mission_submission_recorded after insert on submissions for each row execute function record_mission_submission();
